INSERT INTO `property_listings` VALUES (53, '[{\"key\":\"title\",\"title\":\"عنوان\",\"value\":\"فروش آپارتمان ۱۶۲ متری کلید نخورده_میلاد ۴ مهرشهر\",\"order\":1},{\"key\":\"price\",\"title\":\"قیمت کل\",\"value\":\"‏۲۸,۳۵۰,۰۰۰,۰۰۰ تومان\",\"order\":2},{\"key\":\"pricePerMeter\",\"title\":\"قیمت هر متر\",\"value\":\"‏۱۷۵,۰۰۰,۰۰۰ تومان\",\"order\":5},{\"key\":\"area\",\"title\":\"متراژ\",\"value\":\"162\",\"order\":6},{\"key\":\"rooms\",\"title\":\"اتاق\",\"value\":\"سه\",\"order\":7},{\"key\":\"floor\",\"title\":\"طبقه\",\"value\":\"۴ از ۵\",\"order\":8},{\"key\":\"yearBuilt\",\"title\":\"سال ساخت\",\"value\":\"۱۴۰۴\",\"order\":9},{\"key\":\"totalFloors\",\"title\":\"تعداد کل طبقات\",\"value\":\"۵\",\"order\":10},{\"key\":\"buildingDirection\",\"title\":\"جهت ساختمان\",\"value\":\"جنوبی\",\"order\":12},{\"key\":\"deedType\",\"title\":\"سند\",\"value\":\"تک‌برگ\",\"order\":13},{\"key\":\"occupancyStatus\",\"title\":\"وضعیت سکونت\",\"value\":\"تخلیه\",\"order\":16},{\"key\":\"address\",\"title\":\"آدرس\",\"value\":\"کرج, فاز ۳ مهرشهر\",\"order\":18},{\"key\":\"elevator\",\"title\":\"آسانسور\",\"value\":\"دارد\",\"order\":19},{\"key\":\"parking\",\"title\":\"پارکینگ\",\"value\":\"دارد\",\"order\":20},{\"key\":\"storage\",\"title\":\"انباری\",\"value\":\"دارد\",\"order\":21},{\"key\":\"fullDescription\",\"title\":\"توضیحات\",\"value\":\"۱۶۲ متر | ۳ خواب | طبقه ۴ | رو به نما | سند تک‌برگ\\n\\n✨ واحد خاص در بهترین لوکیشن ارم، میلاد ۴:\\nرو به نما\\n سازه مدرن و خاص منطقه\\n لابی شیک و مبله\\n سالن اجتماعات و سالن ورزش\\n سالن بازی کودک\\n روف‌گاردن - حمام آفتاب\\n ۲ بالکن بزرگ و قابل چیدمان\\n مطبخ کاربردی\\n پارکینگ \\n طبقه ۴، رو به نما\\n کلید نخورده نوساز\\n سند تک‌برگ آماده انتقال\\n\\n واحد به‌صورت خام تحویل شده و **هزینه‌ی کابینت، به‌عنوان تخفیف از قیمت نهایی کسر می‌شود.**\",\"order\":23},{\"key\":\"url\",\"title\":\"لینک\",\"value\":\"https://divar.ir/v/gaEqyt10\",\"order\":24}]', 'کرج', '۱۶۲ متر | ۳ خواب | طبقه ۴ | رو به نما | سند تک‌برگ\n\n✨ واحد خاص در بهترین لوکیشن ارم، میلاد ۴:\nرو به نما\n سازه مدرن و خاص منطقه\n لابی شیک و مبله\n سالن اجتماعات و سالن ورزش\n سالن بازی کودک\n روف‌گاردن - حمام آفتاب\n ۲ بالکن بزرگ و قابل چیدمان\n مطبخ کاربردی\n پارکینگ \n طبقه ۴، رو به نما\n کلید نخورده نوساز\n سند تک‌برگ آماده انتقال\n\n واحد به‌صورت خام تحویل شده و **هزینه‌ی کابینت، به‌عنوان تخفیف از قیمت نهایی کسر می‌شود.**', 'فاز ۳ مهرشهر', '[\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/x8Td43EJjjHygqrtNLiY0w/6f643587-393c-4b05-be6b-6fe90b20885c.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/3gNwsbZNwavH2EUbITx3Zg/7f11684d-bf10-4c07-981c-46a81844d057.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/8wU2PglNPxGNSpdmgvIP7w/8d9ec9a9-26a3-4d6f-832e-574a2f35a829.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/MPvkAQZLaLnnnfPg2zamUg/4df77d25-af47-4960-9547-520e39f8c355.webp\"]', b'0', b'1', 'فروش', 'apartment', '2026-09-02 11:30:55.000000', '2026-09-02 11:31:28.000000', 'فروش آپارتمان ۱۶۲ متری کلید نخورده_میلاد ۴ مهرشهر', 'gaEqyt10', 'https://divar.ir/v/gaEqyt10', 'فروش آپارتمان مهرشهر', b'0');
INSERT INTO `property_listings` VALUES (54, '[{\"key\":\"title\",\"title\":\"عنوان\",\"value\":\"67 دونبش روبه نما_زیرقیمت_مهرشهر بلوار ارم_ میلاد۴\",\"order\":1},{\"key\":\"price\",\"title\":\"قیمت کل\",\"value\":\"‏۶,۳۰۰,۰۰۰,۰۰۰ تومان\",\"order\":2},{\"key\":\"pricePerMeter\",\"title\":\"قیمت هر متر\",\"value\":\"‏۹۴,۰۲۹,۰۰۰ تومان\",\"order\":5},{\"key\":\"area\",\"title\":\"متراژ\",\"value\":\"67\",\"order\":6},{\"key\":\"rooms\",\"title\":\"اتاق\",\"value\":\"یک\",\"order\":7},{\"key\":\"floor\",\"title\":\"طبقه\",\"value\":\"۳ از ۳\",\"order\":8},{\"key\":\"yearBuilt\",\"title\":\"سال ساخت\",\"value\":\"۱۳۸۷\",\"order\":9},{\"key\":\"totalFloors\",\"title\":\"تعداد کل طبقات\",\"value\":\"۳\",\"order\":10},{\"key\":\"unitsPerFloor\",\"title\":\"تعداد واحد در طبقه\",\"value\":\"۲\",\"order\":11},{\"key\":\"deedType\",\"title\":\"سند\",\"value\":\"تک‌برگ\",\"order\":13},{\"key\":\"kitchenType\",\"title\":\"نوع آشپزخانه\",\"value\":\"جزیره\",\"order\":14},{\"key\":\"buildingFacade\",\"title\":\"نمای ساختمان\",\"value\":\"سنگ\",\"order\":15},{\"key\":\"address\",\"title\":\"آدرس\",\"value\":\"کرج, فاز ۳ مهرشهر\",\"order\":18},{\"key\":\"elevator\",\"title\":\"آسانسور\",\"value\":\"ندارد\",\"order\":19},{\"key\":\"parking\",\"title\":\"پارکینگ\",\"value\":\"دارد\",\"order\":20},{\"key\":\"storage\",\"title\":\"انباری\",\"value\":\"دارد\",\"order\":21},{\"key\":\"fullDescription\",\"title\":\"توضیحات\",\"value\":\"(در این لوکیشن واحد با این متراژ و قیمت اصلا نیست)\\n\\n«زیر قیمت منطقه نقد و معاوضه با ماشین »\\n           \\nمهرشهر بلوار ارم خیابان میلاد4 (میلادها)\\n\\nدو نبش و هر دو نبش رو به نمای اصلی غرق نور\\n\\n67 متر سند تک برگ بازسازی شده (آماده انتقال )\\n \\nتازه بازسازی و نقاشی شده اماده سکونت\\nغرق نور و پنجره ها رو به نما\\nکلا 6 واحد طبقه ۳\\nپارکینگ سندی اختصاصی \\nانباری سندی اختصاصی\\nبدون اسانسور \\nکابینت / کف سرامیک\\nکمد دیواری /نمای ساختمان سنگ \\nتراس رو به نما  قابل چیدمان \\nحیاط دار\\nخیابان سر سبز و لوکیشن عالی\\nنقد و معاوضه و تهاتر با خودرو مدل بالا\\n((مالک هستم))\",\"order\":23},{\"key\":\"url\",\"title\":\"لینک\",\"value\":\"https://divar.ir/v/gaXSNDEv\",\"order\":24}]', 'کرج', '(در این لوکیشن واحد با این متراژ و قیمت اصلا نیست)\n\n«زیر قیمت منطقه نقد و معاوضه با ماشین »\n           \nمهرشهر بلوار ارم خیابان میلاد4 (میلادها)\n\nدو نبش و هر دو نبش رو به نمای اصلی غرق نور\n\n67 متر سند تک برگ بازسازی شده (آماده انتقال )\n \nتازه بازسازی و نقاشی شده اماده سکونت\nغرق نور و پنجره ها رو به نما\nکلا 6 واحد طبقه ۳\nپارکینگ سندی اختصاصی \nانباری سندی اختصاصی\nبدون اسانسور \nکابینت / کف سرامیک\nکمد دیواری /نمای ساختمان سنگ \nتراس رو به نما  قابل چیدمان \nحیاط دار\nخیابان سر سبز و لوکیشن عالی\nنقد و معاوضه و تهاتر با خودرو مدل بالا\n((مالک هستم))', 'فاز ۳ مهرشهر', '[\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/4blXuS9MqGTDh8WgYv7CPw/c99708c4-5d53-4451-af42-9d49a707afb7.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/L1JyEi_Yv5Cjqn2FCf1IZg/020d9278-0ea4-4a05-8dd2-d7727f703b73.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/hSAdb2MApKTrncZ4bRnMdg/f4eff2b5-ac2b-490d-9942-26be6f4bca75.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/PiAQpVD_DoXF4sYbZ9ix4g/bb564dc5-9692-4594-8f83-77f75166c124.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/FfDj841tBlzaoKjlWbwYUw/57d4197f-6567-415f-9d9e-eecf7e081965.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/hnr5ddfpewRoalDJWCcpCQ/0c2a181f-3b4d-492c-838b-b47826560937.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/9F4PeHWFAafb1etMLAuF6Q/0ba9ef80-779d-453f-bed2-d3ef879f5b63.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/xxXJpfOxoh47vzYasDWJJA/61200190-4ebd-4f2e-9b5a-646b99ba3cdf.webp\"]', b'0', b'1', 'فروش', 'apartment', '2026-09-02 11:31:08.000000', '2026-09-02 11:31:40.000000', '67 دونبش روبه نما_زیرقیمت_مهرشهر بلوار ارم_ میلاد۴', 'gaXSNDEv', 'https://divar.ir/v/gaXSNDEv', 'فروش آپارتمان مهرشهر', b'0');
