INSERT INTO `property_listings` VALUES (66, '[{\"key\":\"title\",\"title\":\"عنوان\",\"value\":\"فروش آپارتمان ۱۰۰متری\",\"order\":1},{\"key\":\"price\",\"title\":\"قیمت کل\",\"value\":\"‏۷,۵۰۰,۰۰۰,۰۰۰ تومان\",\"order\":2},{\"key\":\"pricePerMeter\",\"title\":\"قیمت هر متر\",\"value\":\"‏۷۵,۰۰۰,۰۰۰ تومان\",\"order\":5},{\"key\":\"area\",\"title\":\"متراژ\",\"value\":\"100\",\"order\":6},{\"key\":\"rooms\",\"title\":\"اتاق\",\"value\":\"دو\",\"order\":7},{\"key\":\"floor\",\"title\":\"طبقه\",\"value\":\"۲ از ۲\",\"order\":8},{\"key\":\"yearBuilt\",\"title\":\"سال ساخت\",\"value\":\"۱۳۸۵\",\"order\":9},{\"key\":\"totalFloors\",\"title\":\"تعداد کل طبقات\",\"value\":\"۲\",\"order\":10},{\"key\":\"unitsPerFloor\",\"title\":\"تعداد واحد در طبقه\",\"value\":\"۴\",\"order\":11},{\"key\":\"buildingDirection\",\"title\":\"جهت ساختمان\",\"value\":\"جنوبی\",\"order\":12},{\"key\":\"kitchenType\",\"title\":\"نوع آشپزخانه\",\"value\":\"اپن\",\"order\":14},{\"key\":\"buildingFacade\",\"title\":\"نمای ساختمان\",\"value\":\"ترکیبی\",\"order\":15},{\"key\":\"occupancyStatus\",\"title\":\"وضعیت سکونت\",\"value\":\"تخلیه\",\"order\":16},{\"key\":\"address\",\"title\":\"آدرس\",\"value\":\"کرج, فاز ۳ مهرشهر\",\"order\":18},{\"key\":\"elevator\",\"title\":\"آسانسور\",\"value\":\"ندارد\",\"order\":19},{\"key\":\"parking\",\"title\":\"پارکینگ\",\"value\":\"دارد\",\"order\":20},{\"key\":\"storage\",\"title\":\"انباری\",\"value\":\"دارد\",\"order\":21},{\"key\":\"fullDescription\",\"title\":\"توضیحات\",\"value\":\"یک اپارتمان ۱۰۰متری فول بازسازی شده با تمام امکانات  با دسترسی محلی عالی در مهرشهرکرج جهت فروش وموقعیت عالی برای سرمایه گذاری وزوجهای جوان .\\nطبقه دوم سندی ،سالن واناق خوابها کاملا پرده خور با نورگیرعالی \\nشامل :\\n ۲ خواب بزرگ  (هردوخواب دارای  کمددیواری بزرگ )\\nبالکن \\nسرویس بهداشتی \\nحمام \\nانباری \\nپارکینگ \\nقیمت اعلامی ۷ میلیارد وپانصد میلیون ،\\n(تخفیف جزعی پای معامله ،خواهشا فقط خریدار تماس بگیرد\\nقبل از بازدید تماس گرفته شود\\n باتشکر ازدیوار\",\"order\":23},{\"key\":\"url\",\"title\":\"لینک\",\"value\":\"https://divar.ir/v/gaduwP6N\",\"order\":24}]', 'کرج', 'یک اپارتمان ۱۰۰متری فول بازسازی شده با تمام امکانات  با دسترسی محلی عالی در مهرشهرکرج جهت فروش وموقعیت عالی برای سرمایه گذاری وزوجهای جوان .\nطبقه دوم سندی ،سالن واناق خوابها کاملا پرده خور با نورگیرعالی \nشامل :\n ۲ خواب بزرگ  (هردوخواب دارای  کمددیواری بزرگ )\nبالکن \nسرویس بهداشتی \nحمام \nانباری \nپارکینگ \nقیمت اعلامی ۷ میلیارد وپانصد میلیون ،\n(تخفیف جزعی پای معامله ،خواهشا فقط خریدار تماس بگیرد\nقبل از بازدید تماس گرفته شود\n باتشکر ازدیوار', 'فاز ۳ مهرشهر', '[\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/MhqB6OQQJD-XC4peRuqK_Q/aae87890-210b-4d9b-8d84-e42ab365c887.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/nml-l7E73TQyblgOHkDuaw/712d7e76-a963-4bc8-980f-d85171c26ea7.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/b4XT7K6p0UPQ3-OcpVhi1Q/12561c7d-3e14-4f6d-8723-872f395f2160.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/MpPBn0vxc-O2S6PtApzKVQ/38d69df3-5d9d-442e-98c5-908b34b4e9ff.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/XpqcmDunBEewTzqRJ9a1Bw/9e01f4cd-c33b-47e7-82d6-e120e5232bd9.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/mWQuRDNbnCJ8RvTTTUXwAA/3de0f3d4-2f53-42d1-8bc6-910752b07195.webp\"]', b'0', b'1', 'فروش', 'apartment', '2026-09-06 11:31:37.000000', '2026-09-06 11:32:09.000000', 'فروش آپارتمان ۱۰۰متری', 'gaduwP6N', 'https://divar.ir/v/gaduwP6N', 'فروش آپارتمان مهرشهر', b'0');
