INSERT INTO `property_listings` VALUES (82, '[{\"key\":\"title\",\"title\":\"عنوان\",\"value\":\"اجاره آپارتمان ۷۲ متری انتهای میلاد یک\",\"order\":1},{\"key\":\"deposit\",\"title\":\"ودیعه\",\"value\":\"‏۸۰۰,۰۰۰,۰۰۰ تومان\",\"order\":3},{\"key\":\"area\",\"title\":\"متراژ\",\"value\":\"72\",\"order\":6},{\"key\":\"rooms\",\"title\":\"اتاق\",\"value\":\"دو\",\"order\":7},{\"key\":\"floor\",\"title\":\"طبقه\",\"value\":\"۲ از ۳\",\"order\":8},{\"key\":\"yearBuilt\",\"title\":\"سال ساخت\",\"value\":\"۱۳۸۶\",\"order\":9},{\"key\":\"totalFloors\",\"title\":\"تعداد کل طبقات\",\"value\":\"۳\",\"order\":10},{\"key\":\"unitsPerFloor\",\"title\":\"تعداد واحد در طبقه\",\"value\":\"۱\",\"order\":11},{\"key\":\"buildingDirection\",\"title\":\"جهت ساختمان\",\"value\":\"جنوبی\",\"order\":12},{\"key\":\"kitchenType\",\"title\":\"نوع آشپزخانه\",\"value\":\"اپن\",\"order\":14},{\"key\":\"address\",\"title\":\"آدرس\",\"value\":\"کرج, آق تپه\",\"order\":18},{\"key\":\"elevator\",\"title\":\"آسانسور\",\"value\":\"ندارد\",\"order\":19},{\"key\":\"parking\",\"title\":\"پارکینگ\",\"value\":\"ندارد\",\"order\":20},{\"key\":\"storage\",\"title\":\"انباری\",\"value\":\"دارد\",\"order\":21},{\"key\":\"balcony\",\"title\":\"بالکن\",\"value\":\"ندارد\",\"order\":22},{\"key\":\"fullDescription\",\"title\":\"توضیحات\",\"value\":\"در انتهای میلاد یکم مهرشهر، کوچه ای بن بست با درختان بلند و سرسبز منتظر حضور شماست. \\n۷۲ متر آپارتمان در یک ساختمان ۳ واحدی بسیار آرام \\nطبقه دوم\\nدوخوابه \\nاز دو طرف نورگیر دارد و در دل شهر منظره ای سرسبز و شگفت انگیز دارد.\\nسرویس توالت ایرانی و فرنگی\\nکف پارکت\\nانباری دارد\\nپارکینگ اختصاصی مقابل ساختمان دارد نه داخل ساختمان. عکس جای پارک مقابل ورودی زیبای ساختمان  هست\\nدسترسی آسان \\nنانوایی،  کافی شاپ، افق کوروش و همه ی مغازه ها سر کوچه به فاصله ۳ دقیقه پیاده\\nترجیحا به دونفر اجاره داده می شود\",\"order\":23},{\"key\":\"url\",\"title\":\"لینک\",\"value\":\"https://divar.ir/v/gakyCqZM\",\"order\":24}]', 'کرج', 'در انتهای میلاد یکم مهرشهر، کوچه ای بن بست با درختان بلند و سرسبز منتظر حضور شماست. \n۷۲ متر آپارتمان در یک ساختمان ۳ واحدی بسیار آرام \nطبقه دوم\nدوخوابه \nاز دو طرف نورگیر دارد و در دل شهر منظره ای سرسبز و شگفت انگیز دارد.\nسرویس توالت ایرانی و فرنگی\nکف پارکت\nانباری دارد\nپارکینگ اختصاصی مقابل ساختمان دارد نه داخل ساختمان. عکس جای پارک مقابل ورودی زیبای ساختمان  هست\nدسترسی آسان \nنانوایی،  کافی شاپ، افق کوروش و همه ی مغازه ها سر کوچه به فاصله ۳ دقیقه پیاده\nترجیحا به دونفر اجاره داده می شود', 'آق تپه', '[\"https://s100.divarcdn.com/static/videos/thumbnails/thumbnail/90968c50-a25c-4e0d-bf36-e107bd3ac2c0.jpg\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/YYQp2KTWJ6_zqAFf6r93lQ/b77f7f4d-5264-4241-abdc-ada724e60a59.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/Py86mkE1lnlnQXeOL7N06Q/4b78c872-5c33-4134-9572-6540ad9a94e4.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/tzbZkACzlUBW8ZKeWKSx-g/9b31bb9a-331a-4fa8-b37c-8d1af744cd3e.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/Y_QvQqVuC9BbpadUeK8jJg/ebd1175f-cab7-4292-a8fd-5d2b141f794b.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/Ug6-s237Y3HIXrEqThSvdA/8e1dc8c9-faa5-4a23-b326-e2f0019cf81c.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/vfeCfIIR_X06UDM2jCyIMw/570fe8c1-0089-4903-8fab-9cf0273681e1.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/-dt-WQNwDZRV2UOHkM2pIw/3ed96084-74d7-4473-9cfa-e55c35463d26.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/3thsM5IkZmRZtNyomZ7U3w/7253e27a-aa93-4b45-a430-c0253787af47.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/mPp29eJeD6aqfIwj-Cr78A/6d63fa86-68c6-4d3e-a6a0-c82836364ea8.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/mlM3lwwZ3Pq14g8YciBdGg/5dc127c6-2dfb-484e-a04d-4e98072eaef7.webp\"]', b'0', b'1', 'اجاره', 'apartment', '2026-09-12 11:30:22.000000', '2026-09-12 11:31:16.000000', 'اجاره آپارتمان ۷۲ متری انتهای میلاد یک', 'gakyCqZM', 'https://divar.ir/v/gakyCqZM', 'اجاره آپارتمان مهرشهر', b'0');
INSERT INTO `property_listings` VALUES (83, '[{\"key\":\"title\",\"title\":\"عنوان\",\"value\":\"اجاره آپارتمان شیک مهرشهر\",\"order\":1},{\"key\":\"deposit\",\"title\":\"ودیعه\",\"value\":\"800000000\",\"order\":3},{\"key\":\"monthlyRent\",\"title\":\"اجاره ماهانه\",\"value\":\"18500000\",\"order\":4},{\"key\":\"area\",\"title\":\"متراژ\",\"value\":\"72\",\"order\":6},{\"key\":\"rooms\",\"title\":\"اتاق\",\"value\":\"دو\",\"order\":7},{\"key\":\"floor\",\"title\":\"طبقه\",\"value\":\"۲ از ۳\",\"order\":8},{\"key\":\"yearBuilt\",\"title\":\"سال ساخت\",\"value\":\"۱۳۸۶\",\"order\":9},{\"key\":\"totalFloors\",\"title\":\"تعداد کل طبقات\",\"value\":\"۳\",\"order\":10},{\"key\":\"unitsPerFloor\",\"title\":\"تعداد واحد در طبقه\",\"value\":\"۱\",\"order\":11},{\"key\":\"buildingDirection\",\"title\":\"جهت ساختمان\",\"value\":\"جنوبی\",\"order\":12},{\"key\":\"kitchenType\",\"title\":\"نوع آشپزخانه\",\"value\":\"اپن\",\"order\":14},{\"key\":\"address\",\"title\":\"آدرس\",\"value\":\"کرج, آق تپه\",\"order\":18},{\"key\":\"elevator\",\"title\":\"آسانسور\",\"value\":\"ندارد\",\"order\":19},{\"key\":\"parking\",\"title\":\"پارکینگ\",\"value\":\"ندارد\",\"order\":20},{\"key\":\"storage\",\"title\":\"انباری\",\"value\":\"دارد\",\"order\":21},{\"key\":\"balcony\",\"title\":\"بالکن\",\"value\":\"ندارد\",\"order\":22},{\"key\":\"fullDescription\",\"title\":\"توضیحات\",\"value\":\"انتهای میلاد یک در مهرشهر کوچه ای بن بست با درختان بلند و سرسبز منتظر حضور شماست. \\n۷۲ متر آپارتمان در یک ساختمان ۳ واحدی بسیار آرام \\nطبقه دوم\\nدوخوابه \\nاز دو طرف نورگیر دارد و در دل شهر منظره ای سرسبز و شگفت انگیز دارد.\\nسرویس توالت ایرانی و فرنگی\\nکف پارکت\\nانباری دارد\\nپارکینگ اختصاصی مقابل ساختمان دارد نه داخل ساختمان. عکس جای پارک مقابل ورودی زیبای ساختمان  هست\\nدسترسی آسان \\nنانوایی،  کافی شاپ، افق کوروش و همه ی مغازه ها سر کوچه به فاصله ۳ دقیقه پیاده\\nترجیحا به دونفر اجاره داده می شود\\nیک میلیارد و سیصد قابل تبدیل\",\"order\":23},{\"key\":\"url\",\"title\":\"لینک\",\"value\":\"https://divar.ir/v/gakaicuY\",\"order\":24}]', 'کرج', 'انتهای میلاد یک در مهرشهر کوچه ای بن بست با درختان بلند و سرسبز منتظر حضور شماست. \n۷۲ متر آپارتمان در یک ساختمان ۳ واحدی بسیار آرام \nطبقه دوم\nدوخوابه \nاز دو طرف نورگیر دارد و در دل شهر منظره ای سرسبز و شگفت انگیز دارد.\nسرویس توالت ایرانی و فرنگی\nکف پارکت\nانباری دارد\nپارکینگ اختصاصی مقابل ساختمان دارد نه داخل ساختمان. عکس جای پارک مقابل ورودی زیبای ساختمان  هست\nدسترسی آسان \nنانوایی،  کافی شاپ، افق کوروش و همه ی مغازه ها سر کوچه به فاصله ۳ دقیقه پیاده\nترجیحا به دونفر اجاره داده می شود\nیک میلیارد و سیصد قابل تبدیل', 'آق تپه', '[\"https://s100.divarcdn.com/static/videos/thumbnails/thumbnail/06f6b39d-297e-4649-838e-35a53b8c1d93.jpg\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/ZlIe8j5k9pkJTbSD8i_yrw/0ce1047f-611f-4467-97bd-3c1c0b5fc696.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/BAC_HewgBSxHwPDL_k6EHA/63bcb810-eebf-4ced-86b9-27b2e8cb2d9d.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/nxlCao_nPDmn_RlxYasm6w/4a2a3d84-638f-4bd7-aded-c604f38bafa2.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/eooqLnXGaw7JOPthP-bWwA/8678eaec-4210-4187-ad10-2e104c7b2928.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/a6lEDaiszNylcQQaO2b6aQ/2384374d-7cbe-4644-8b77-7a27dcc12222.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/Acfvz4Hx5Qqj7SGZxNOh4w/db3bb0f8-5f21-4a40-a842-c400829d9c14.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/bpLBvz2Leji_p7gN1uaj5A/ce7ee7d8-3005-41f1-b880-c489eb53984a.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/qNwN6wX3iyisDcFkWn8Zdw/b4364d57-ab86-4d9a-b408-ffbcfff54e8c.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/sqfJXgK_xHjRKVaN8YWkyA/3d50c07f-ea1f-4c55-bb57-be1c5e2bf88a.webp\"]', b'0', b'1', 'اجاره', 'apartment', '2026-09-12 11:30:25.000000', '2026-09-12 11:31:28.000000', 'اجاره آپارتمان شیک مهرشهر', 'gakaicu