INSERT INTO `property_listings` VALUES (89, '[{\"key\":\"title\",\"title\":\"عنوان\",\"value\":\"خانه ۸۵ متری غرق نور دوکله\",\"order\":1},{\"key\":\"deposit\",\"title\":\"ودیعه\",\"value\":\"‏۱,۰۰۰,۰۰۰,۰۰۰ تومان\",\"order\":3},{\"key\":\"area\",\"title\":\"متراژ\",\"value\":\"85\",\"order\":6},{\"key\":\"rooms\",\"title\":\"اتاق\",\"value\":\"دو\",\"order\":7},{\"key\":\"floor\",\"title\":\"طبقه\",\"value\":\"۱\",\"order\":8},{\"key\":\"yearBuilt\",\"title\":\"سال ساخت\",\"value\":\"۱۳۸۷\",\"order\":9},{\"key\":\"address\",\"title\":\"آدرس\",\"value\":\"کرج, آق تپه\",\"order\":18},{\"key\":\"elevator\",\"title\":\"آسانسور\",\"value\":\"ندارد\",\"order\":19},{\"key\":\"parking\",\"title\":\"پارکینگ\",\"value\":\"دارد\",\"order\":20},{\"key\":\"storage\",\"title\":\"انباری\",\"value\":\"دارد\",\"order\":21},{\"key\":\"fullDescription\",\"title\":\"توضیحات\",\"value\":\"واحد روبه افتاب \\nدوکله \\nغرق نور\\nفول بازسازی شده\\nگاز رومیزی \\nسینک گرانیتی \\nپکیج \\nکلا ۴ واحد \\nدوخواب نور مستقیم\\nیک خواب مستر\",\"order\":23},{\"key\":\"url\",\"title\":\"لینک\",\"value\":\"https://divar.ir/v/gamSUYBU\",\"order\":24}]', 'کرج', 'واحد روبه افتاب \nدوکله \nغرق نور\nفول بازسازی شده\nگاز رومیزی \nسینک گرانیتی \nپکیج \nکلا ۴ واحد \nدوخواب نور مستقیم\nیک خواب مستر', 'آق تپه', '[\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/X3JXW_2pjcP_g7SorQSPBQ/22e0e1dd-9b98-4e29-b829-202a888fb869.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/h-ILp-gO2-cnpUuaQr9rqg/82b42bdc-8303-44b8-ae72-9bb6ec04a14a.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/BorCdRXWvDZyCXKfCZuxXw/ef3cc8ee-7324-42d8-bdf4-c2e220108a5e.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/VlFa30pEQNIxrIx7uwh4HA/8e083f90-4684-416e-a9f4-792174d12ab7.webp\"]', b'0', b'1', 'اجاره', 'apartment', '2026-09-14 06:30:22.000000', '2026-09-14 06:30:48.000000', 'خانه ۸۵ متری غرق نور دوکله', 'gamSUYBU', 'https://divar.ir/v/gamSUYBU', 'اجاره آپارتمان مهرشهر', b'0');
INSERT INTO `property_listings` VALUES (90, '[{\"key\":\"title\",\"title\":\"عنوان\",\"value\":\"واحد ۱۳۶ متری خوش نقشه مهرشهر میلاد۴\",\"order\":1},{\"key\":\"price\",\"title\":\"قیمت کل\",\"value\":\"‏۲۹,۹۰۰,۰۰۰,۰۰۰ تومان\",\"order\":2},{\"key\":\"pricePerMeter\",\"title\":\"قیمت هر متر\",\"value\":\"‏۲۱۹,۸۵۲,۰۰۰ تومان\",\"order\":5},{\"key\":\"area\",\"title\":\"متراژ\",\"value\":\"136\",\"order\":6},{\"key\":\"rooms\",\"title\":\"اتاق\",\"value\":\"سه\",\"order\":7},{\"key\":\"floor\",\"title\":\"طبقه\",\"value\":\"۱ از ۶\",\"order\":8},{\"key\":\"yearBuilt\",\"title\":\"سال ساخت\",\"value\":\"۱۴۰۲\",\"order\":9},{\"key\":\"totalFloors\",\"title\":\"تعداد کل طبقات\",\"value\":\"۶\",\"order\":10},{\"key\":\"unitsPerFloor\",\"title\":\"تعداد واحد در طبقه\",\"value\":\"۶\",\"order\":11},{\"key\":\"buildingDirection\",\"title\":\"جهت ساختمان\",\"value\":\"شمالی\",\"order\":12},{\"key\":\"deedType\",\"title\":\"سند\",\"value\":\"تک‌برگ\",\"order\":13},{\"key\":\"kitchenType\",\"title\":\"نوع آشپزخانه\",\"value\":\"جزیره\",\"order\":14},{\"key\":\"buildingFacade\",\"title\":\"نمای ساختمان\",\"value\":\"سنگ\",\"order\":15},{\"key\":\"occupancyStatus\",\"title\":\"وضعیت سکونت\",\"value\":\"مالک سکونت دارد\",\"order\":16},{\"key\":\"address\",\"title\":\"آدرس\",\"value\":\"کرج, آق تپه\",\"order\":18},{\"key\":\"elevator\",\"title\":\"آسانسور\",\"value\":\"دارد\",\"order\":19},{\"key\":\"parking\",\"title\":\"پارکینگ\",\"value\":\"دارد\",\"order\":20},{\"key\":\"storage\",\"title\":\"انباری\",\"value\":\"دارد\",\"order\":21},{\"key\":\"fullDescription\",\"title\":\"توضیحات\",\"value\":\"مجتمع برند منطقه\\n\\nروف گاردن\\n\\nحمام آفتاب\\n\\nسالن ورزشی\\n\\nسالن اجتماعات\\n\\nمهد کودک\\n\\nلابی من و نگهبانی ۲۴ ساعته\\n\\nدوربین مدار بسته\\n\\nگلکاری و فضای سبز داخل لابی ، حیاط و روف گاردن\\n\\nدرب پارکینگ ریموت\\n\\nآیفون تصویری\\n\\nکلوزت روم\\n\\nمطبخ\\n\\nبسیار خوش نقشه و بدون پرتی فضا\\n\\nتراس بزرگ و قابل چیدمان\\n\\nحیاط خلوت ۴ متر مربع که جزء متراژ سند نمیباشد\\n\\nمتراژ واحد ۱۳۶ متر \\n\\nسند تک برگ\\n\\nطبقه اول ، بالای لابی ، پارکینگ در طبقه منفی یک میباشد\\n\\nساختمان ساکت و آرام و دنج\\n\\nبلوک جنوبی جهت واحد شمالی\\n\\nطراحی و تجهیز دکوراسیون داخلی به صورت کامل با متریال درجه یک شامل موارد زیر:\\n\\nرنگ ، نور پردازی ،ترمو وود ، تی وی وال ، کابینت ام دی اف ،۲ عدد سینک گرانیتی ، گاز توکار ایتالیایی ، کلوزت روم و کمد دیواری ام دی اف ، شیر آلات ، روشویی ، فرنگی  ، داکت اسپلیت ، پکیج ، حوله خشک کن ، قرنیز ،یراق کابینت و کمد بلوم اتریش\\n\\nقابلیت رهن تا ۳ میلیارد\\n\\nآدرس مهرشهر بلوار ارم میلاد چهار مجتمع پایا بلوک جنوبی\",\"order\":23},{\"key\":\"url\",\"title\":\"لینک\",\"value\":\"https://divar.ir/v/gamu6cn8\",\"order\":24}]', 'کرج', 'مجتمع برند منطقه\n\nروف گاردن\n\nحمام آفتاب\n\nسالن ورزشی\n\nسالن اجتماعات\n\nمهد کودک\n\nلابی من و نگهبانی ۲۴ ساعته\n\nدوربین مدار بسته\n\nگلکاری و فضای سبز داخل لابی ، حیاط و روف گاردن\n\nدرب پارکینگ ریموت\n\nآیفون تصویری\n\nکلوزت روم\n\nمطبخ\n\nبسیار خوش نقشه و بدون پرتی فضا\n\nتراس بزرگ و قابل چیدمان\n\nحیاط خلوت ۴ متر مربع که جزء متراژ سند نمیباشد\n\nمتراژ واحد ۱۳۶ متر \n\nسند تک برگ\n\nطبقه اول ، بالای لابی ، پارکینگ در طبقه منفی یک میباشد\n\nساختمان ساکت و آرام و دنج\n\nبلوک جنوبی جهت واحد شمالی\n\nطراحی و تجهیز دکوراسیون داخلی به صورت کامل با متریال درجه یک شامل موارد زیر:\n\nرنگ ، نور پردازی ،ترمو وود ، تی وی وال ، کابینت ام دی اف ،۲ عدد سینک گرانیتی ، گاز توکار ایتالیایی ، کلوزت روم و کمد دیواری ام دی اف ، شیر آلات ، روشویی ، فرنگی  ، داکت اسپلیت ، پکیج ، حوله خشک کن ، قرنیز ،یراق کابینت و کمد بلوم اتریش\n\nقابلیت رهن تا ۳ میلیارد\n\nآدرس مهرشهر بلوار ارم میلاد چهار مجتمع پایا بلوک جنوبی', 'آق تپه', '[\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/0VD5tsorM5Q0UbGfUwvnDA/f88b65ce-0a3a-44f4-bca7-a461cadbf1cb.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/l6Gdr-FOskojD2NFKkttrg/a4d79448-6c44-4f8e-9243-45b282a7d346.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/_J4s_uEEIieNl287ICdvdw/0b9b2795-2d45-4743-ac1b-9458329a416a.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/5Jibi8kklaXapOai7iiAMw/da98e9cd-3f31-4217-a819-4d9c85f019a7.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/xbzPuYdZH5XpF8dKoZOLEQ/4fc5604e-b1e8-43f3-9128-925448de18e1.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/CLNZSM5QarIrgpn6VnK5Zw/eefc4d15-3a06-4613-9d68-9b58812d9561.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/c-RY5KkOeVfkE9HI9p_WRg/125ee724-d041-4c96-a652-6ee646ff41e3.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/rJoBU17bR57gGPe1Y_movA/32cdb0eb-1857-4f8e-85d1-2a20acb836cd.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/NKI8a6-zfrCFg77O7NOcJA/90c8f5ce-9f34-4d6b-a5f1-3c1dfde0e49e.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/gS81r5bK_OlIEDpbVqMESw/62f69f63-6385-482c-9102-9aa54bb623a6.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/P4bH70dzW54gTR3szdbAxA/c9cc3461-60ee-4458-ab42-1613fc0eabae.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/YehN6hnDPIujIEudWf8VzA/924b75d6-472d-4f6b-9796-169b27eff317.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/Bi6QTv8TlFQwRf8xOyIE3g/87b926cd-10db-4b9e-a927-91c8cefdc3c9.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/eEAjkYlpev47PQf4WvJC_Q/945208b3-a215-477c-8e5e-390228ff39a7.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/f4MOhjQMjjC17qwQ8PmUew/10144329-f0ad-4d97-9df0-2d3d6f19fe7a.webp\"]', b'0', b'1', 'فروش', 'apartment', '2026-09-14 06:31:19.000000', '2026-09-14 06:31:55.000000', 'واحد ۱۳۶ متری خوش نقشه مهرشهر میلاد۴', 'gamu6cn8', 'https://divar.ir/v/gamu6cn8', 'فروش آپارتمان مهرشهر', b'0');
