INSERT INTO `property_listings` VALUES (93, '[{\"key\":\"title\",\"title\":\"عنوان\",\"value\":\"فروش آپارتمان ۸۰ متری\",\"order\":1},{\"key\":\"price\",\"title\":\"قیمت کل\",\"value\":\"‏۱۶,۰۰۰,۰۰۰,۰۰۰ تومان\",\"order\":2},{\"key\":\"pricePerMeter\",\"title\":\"قیمت هر متر\",\"value\":\"‏۲۰۰,۰۰۰,۰۰۰ تومان\",\"order\":5},{\"key\":\"area\",\"title\":\"متراژ\",\"value\":\"80\",\"order\":6},{\"key\":\"rooms\",\"title\":\"اتاق\",\"value\":\"دو\",\"order\":7},{\"key\":\"floor\",\"title\":\"طبقه\",\"value\":\"۴ از ۴\",\"order\":8},{\"key\":\"yearBuilt\",\"title\":\"سال ساخت\",\"value\":\"۱۳۹۶\",\"order\":9},{\"key\":\"totalFloors\",\"title\":\"تعداد کل طبقات\",\"value\":\"۴\",\"order\":10},{\"key\":\"unitsPerFloor\",\"title\":\"تعداد واحد در طبقه\",\"value\":\"۲\",\"order\":11},{\"key\":\"buildingDirection\",\"title\":\"جهت ساختمان\",\"value\":\"شمالی\",\"order\":12},{\"key\":\"deedType\",\"title\":\"سند\",\"value\":\"تک‌برگ\",\"order\":13},{\"key\":\"kitchenType\",\"title\":\"نوع آشپزخانه\",\"value\":\"اپن\",\"order\":14},{\"key\":\"buildingFacade\",\"title\":\"نمای ساختمان\",\"value\":\"سنگ\",\"order\":15},{\"key\":\"occupancyStatus\",\"title\":\"وضعیت سکونت\",\"value\":\"مستاجر سکونت دارد\",\"order\":16},{\"key\":\"address\",\"title\":\"آدرس\",\"value\":\"کرج, آق تپه\",\"order\":18},{\"key\":\"elevator\",\"title\":\"آسانسور\",\"value\":\"دارد\",\"order\":19},{\"key\":\"parking\",\"title\":\"پارکینگ\",\"value\":\"دارد\",\"order\":20},{\"key\":\"storage\",\"title\":\"انباری\",\"value\":\"دارد\",\"order\":21},{\"key\":\"fullDescription\",\"title\":\"توضیحات\",\"value\":\"یک دستگاه آپارتمان 80متری \\nفول امکانات ، تراس ، هود ، \\nاجاق گاز ، پکیج ، کابینت MDF\\nدرب ضد سرقت ، آیفون تصویری\\nپنجره دو جداره ، کف سرامیک \\nنما سنگ ، آپارتمان آرام ، همسایگان\\nمحترم ، پارکینگ ، انباری ، کاملا مجهز\\nبه فروش می‌رسد ‌. \\nلطفاً از قیمت تعجب نکنید ، با توجه به \\nگرانی مصالح و متریال ، ملک هم گران شده .\\nلطفاً در ساعت های ذکر شده تماس بگیرید ، \\n10صبح الی 19 شب\",\"order\":23},{\"key\":\"url\",\"title\":\"لینک\",\"value\":\"https://divar.ir/v/gany8woL\",\"order\":24}]', 'کرج', 'یک دستگاه آپارتمان 80متری \nفول امکانات ، تراس ، هود ، \nاجاق گاز ، پکیج ، کابینت MDF\nدرب ضد سرقت ، آیفون تصویری\nپنجره دو جداره ، کف سرامیک \nنما سنگ ، آپارتمان آرام ، همسایگان\nمحترم ، پارکینگ ، انباری ، کاملا مجهز\nبه فروش می‌رسد ‌. \nلطفاً از قیمت تعجب نکنید ، با توجه به \nگرانی مصالح و متریال ، ملک هم گران شده .\nلطفاً در ساعت های ذکر شده تماس بگیرید ، \n10صبح الی 19 شب', 'آق تپه', '[\"https://s100.divarcdn.com/static/photo/neda/webp_post/HDus4tP6896BNZBqThPzEQ/b09c9cb3-bd49-45ed-96d9-8db48891981c.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/_FHRKagtYFv8J2MVjhiEWA/f3ea63cc-b59e-4689-8979-e63cc5e2359f.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/-8Z1msgBexQslmmpaMEIqA/73c344c2-3df8-4740-9b35-f6a718579c22.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/ZlqmbYg5EFT9NZmBykyKtQ/562e1202-a751-4c3d-8f75-82315fa1428f.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/gKEZaEMuUUWujNU2v6Nhkw/f27174c5-e1a7-46eb-9599-1b3f18346ccc.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/BVUWqGSkeeC2eU2uxtwfyA/de465fbe-472b-48bb-8871-789242903bc2.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/lYBSPMjXEoA5aJSL2dXEIw/c2cf51c0-86eb-4154-8a4a-408fd1f54ca7.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/O-vEmN70cWhx9tgV_4HBNw/eb965236-4948-484c-8041-50e305e4d6e8.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/iT-dudKe17AdM4MTDwiEmg/45b73a4d-9620-4c3d-b41d-d21b54f9637e.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/k5iH5gxojwSy5oFOKwmlBA/fd2d0b62-f0e1-4288-94cc-e578d585ae54.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/rI9-5VNTcxatrg2PeCFppQ/c1071a5c-543c-4f59-8d04-d55962ae40ca.webp\"]', b'0', b'1', 'فروش', 'apartment', '2026-09-14 11:31:13.000000', '2026-09-14 11:31:48.000000', 'فروش آپارتمان ۸۰ متری', 'gany8woL', 'https://divar.ir/v/