INSERT INTO `property_listings` VALUES (94, '[{\"key\":\"title\",\"title\":\"عنوان\",\"value\":\"رهن کامل واحد ۹۷ متری ، نوساز ، مناسب عروس‌داماد\",\"order\":1},{\"key\":\"deposit\",\"title\":\"ودیعه\",\"value\":\"‏۱,۵۰۰,۰۰۰,۰۰۰ تومان\",\"order\":3},{\"key\":\"area\",\"title\":\"متراژ\",\"value\":\"97\",\"order\":6},{\"key\":\"rooms\",\"title\":\"اتاق\",\"value\":\"دو\",\"order\":7},{\"key\":\"floor\",\"title\":\"طبقه\",\"value\":\"۱\",\"order\":8},{\"key\":\"yearBuilt\",\"title\":\"سال ساخت\",\"value\":\"۱۴۰۵\",\"order\":9},{\"key\":\"buildingDirection\",\"title\":\"جهت ساختمان\",\"value\":\"شمالی\",\"order\":12},{\"key\":\"address\",\"title\":\"آدرس\",\"value\":\"کرج, باغستان\",\"order\":18},{\"key\":\"elevator\",\"title\":\"آسانسور\",\"value\":\"دارد\",\"order\":19},{\"key\":\"parking\",\"title\":\"پارکینگ\",\"value\":\"دارد\",\"order\":20},{\"key\":\"storage\",\"title\":\"انباری\",\"value\":\"دارد\",\"order\":21},{\"key\":\"fullDescription\",\"title\":\"توضیحات\",\"value\":\" رهن کامل واحد ۹۷ متری | نوساز و عروس‌داماد\\n\\n▪️ ۹۷ متر\\n▪️ شمالی‌غربی و خوش‌نور\\n▪️ نوساز و بسیار شیک\\n▪️ واحد عروس‌داماد، فوق‌العاده تمیز\\n▪️ لابی شیک و مجلل\\n▪️ سرایداری\\n▪️ ساختمان با مشاعات مرتب و باکیفیت\\n▪️ مناسب سکونت خانواده و زوج‌های جوان\\n\\n✨ واحدی شیک، تمیز و آماده سکونت؛ مناسب افرادی که دنبال ساختمان باکیفیت و امکانات کامل هستند.\\n\\n جهت هماهنگی بازدید تماس بگیرید.\\nخانم وجدانی\",\"order\":23},{\"key\":\"url\",\"title\":\"لینک\",\"value\":\"https://divar.ir/v/ganWv0jZ\",\"order\":24}]', 'کرج', ' رهن کامل واحد ۹۷ متری | نوساز و عروس‌داماد\n\n▪️ ۹۷ متر\n▪️ شمالی‌غربی و خوش‌نور\n▪️ نوساز و بسیار شیک\n▪️ واحد عروس‌داماد، فوق‌العاده تمیز\n▪️ لابی شیک و مجلل\n▪️ سرایداری\n▪️ ساختمان با مشاعات مرتب و باکیفیت\n▪️ مناسب سکونت خانواده و زوج‌های جوان\n\n✨ واحدی شیک، تمیز و آماده سکونت؛ مناسب افرادی که دنبال ساختمان باکیفیت و امکانات کامل هستند.\n\n جهت هماهنگی بازدید تماس بگیرید.\nخانم وجدانی', 'باغستان', '[\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/cYMzYyJQMjP8NOYDJw0mMw/0c079dad-8dae-4967-b230-7d333858516b.webp\"]', b'0', b'1', 'اجاره', 'apartment', '2026-09-14 13:27:09.000000', '2026-09-14 13:27:37.000000', 'رهن کامل واحد ۹۷ متری ، نوساز ، مناسب عروس‌داماد', 'ganWv0jZ', 'https://divar.ir/v/ganWv0jZ', 'اجاره  ساماندهی کیانمه', b'0');
