INSERT INTO `property_listings` VALUES (100, '[{\"key\":\"title\",\"title\":\"عنوان\",\"value\":\"هم خونه خانم\",\"order\":1},{\"key\":\"deposit\",\"title\":\"ودیعه\",\"value\":\"‏۵۰,۰۰۰,۰۰۰ تومان\",\"order\":3},{\"key\":\"area\",\"title\":\"متراژ\",\"value\":\"70\",\"order\":6},{\"key\":\"rooms\",\"title\":\"اتاق\",\"value\":\"یک\",\"order\":7},{\"key\":\"floor\",\"title\":\"طبقه\",\"value\":\"۵\",\"order\":8},{\"key\":\"yearBuilt\",\"title\":\"سال ساخت\",\"value\":\"۱۳۹۸\",\"order\":9},{\"key\":\"kitchenType\",\"title\":\"نوع آشپزخانه\",\"value\":\"اپن\",\"order\":14},{\"key\":\"address\",\"title\":\"آدرس\",\"value\":\"کرج, کیانمهر\",\"order\":18},{\"key\":\"elevator\",\"title\":\"آسانسور\",\"value\":\"دارد\",\"order\":19},{\"key\":\"parking\",\"title\":\"پارکینگ\",\"value\":\"دارد\",\"order\":20},{\"key\":\"storage\",\"title\":\"انباری\",\"value\":\"ندارد\",\"order\":21},{\"key\":\"fullDescription\",\"title\":\"توضیحات\",\"value\":\" هم‌خانه خانم در شهرک ابریشم | واحد ۷۰ متری\\n\\nبرای یک واحد ۷۰ متری یک‌خوابه در شهرک ابریشم، به دنبال یک هم‌خانه خانم مرتب، مسئولیت‌پذیر، آرام و بدون حاشیه هستم.\\n\\nترجیحاً فردی شاغل یا دارای برنامه کاری/تحصیلی منظم باشد.\\nمحیط خانه آرام و محترمانه است و نظافت، حفظ حریم شخصی و رعایت حقوق متقابل برایمان مهم است.\\n\\n✨ مناسب برای کسی که دنبال یک فضای آرام و بی‌دردسر برای زندگی است.\\n\\n ودیعه: ۵۰ میلیون تومان\\n اجاره: ۵ میلیون تومان\\n متراژ: ۷۰ متر | یک‌خوابه\\n محدوده: شهرک ابریشم\\n\\nلطفاً فقط در صورت داشتن شرایط مناسب پیام دهید تا جزئیات بیشتر و هماهنگی بازدید اعلام شود.\",\"order\":23},{\"key\":\"url\",\"title\":\"لینک\",\"value\":\"https://divar.ir/v/ganux1hZ\",\"order\":24}]', 'کرج', ' هم‌خانه خانم در شهرک ابریشم | واحد ۷۰ متری\n\nبرای یک واحد ۷۰ متری یک‌خوابه در شهرک ابریشم، به دنبال یک هم‌خانه خانم مرتب، مسئولیت‌پذیر، آرام و بدون حاشیه هستم.\n\nترجیحاً فردی شاغل یا دارای برنامه کاری/تحصیلی منظم باشد.\nمحیط خانه آرام و محترمانه است و نظافت، حفظ حریم شخصی و رعایت حقوق متقابل برایمان مهم است.\n\n✨ مناسب برای کسی که دنبال یک فضای آرام و بی‌دردسر برای زندگی است.\n\n ودیعه: ۵۰ میلیون تومان\n اجاره: ۵ میلیون تومان\n متراژ: ۷۰ متر | یک‌خوابه\n محدوده: شهرک ابریشم\n\nلطفاً فقط در صورت داشتن شرایط مناسب پیام دهید تا جزئیات بیشتر و هماهنگی بازدید اعلام شود.', 'کیانمهر', '[\"https://s100.divarcdn.com/static/photo/neda/webp_post/7vDuSmOJPOw_oAa6QLYG-A/dfffca89-ecdf-4b86-8504-b24ea596ae1f.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/inR41Dl7Ynf0vx6gx5HwkQ/9d532d4f-8648-4622-a054-b3dab21d395c.webp\"]', b'0', b'1', 'اجاره', 'apartment', '2026-09-14 13:37:42.000000', '2026-09-14 13:38:20.000000', 'هم خونه خانم', 'ganux1hZ', 'https://divar.ir/v/ganux1hZ', 'فروش ابریشم پیام', b'0');
