ps://divar.ir/v/gaomyDTo\",\"order\":24}]', 'کرج', 'واحد ۹۳ متری رو به نما طبقه دوم بهترین لوکیشن کیانمهر گلستان ۴، فول ، پارگینک انباری اسانسور ، سند تک برگ ، رهن مستاجر به مبلغ یک میلیارد تا ۱۴۰۶/۰۵/۲۵ ، لوکیشن و دسترسی عالی به همه فروشگاه های زنجیره ای در کنار ساختمان. واقع در کیانمهر بلوار ازادی نبش گلستان ۴ ، مالک هستم. امکان دریافت وام. فروش فوری به علت مهاجرت', 'کیانمهر', '[\"https://s100.divarcdn.com/static/videos/thumbnails/thumbnail/32a30adf-2203-4a3e-8755-3f3522b86712.jpg\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/n4_icLoJPqQRfIQhLEoJvQ/9f3436a2-954d-44c6-b06d-defd34aa0f76.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/ry78suYO7DaVwkR_eycExA/6b77dea9-2720-4880-bc7c-b2ef8b367192.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/kwHEItApnmrep-2_UOabCg/e7d5118c-3bf8-48fa-b2e0-c024e3613eb6.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/QiBWmYkONRUQZa8Y2iyZnQ/7c9caeef-0c70-4f2d-9193-a297db3f2ef1.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/tXbWabUjhqejxPSFE8qyrQ/3ffbb5f8-5063-4c92-a22f-c81e96acf6db.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/HoEMn6h9ScU06EXzSABCOA/2120b595-78ad-4af9-9db7-7d67715ceb0f.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/BKgUTUPfXBErWHghEB_ojA/4a32e939-1a72-45f1-be69-d5c7b111ac1e.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/1oPS2eOdW7mljUSKVn1_eQ/dc7be1dc-f6ce-4e62-927f-05f4c777e1ee.webp\",\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/W6UYAko4YAFBg_lrv6V3Rg/169aa128-65ce-4758-95b4-beb5ce616ea8.webp\"]', b'0', b'1', 'فروش', 'apartment', '2026-09-15 04:39:47.000000', '2026-09-15 04:41:00.000000', 'فروش اپارتمان سندی ۹۳ متری گلستان۴ کیانمهر', 'gaomyDTo', 'https://divar.ir/v/gaomyDTo', 'فروش ابریشم پیام', b'0');
INSERT INTO `property_listings` VALUES (111, '[{\"key\":\"title\",\"title\":\"عنوان\",\"value\":\"آپارتمان فروشی انتهای کیانمهر شهرک ابریشم\",\"order\":1},{\"key\":\"price\",\"title\":\"قیمت کل\",\"value\":\"‏۳,۸۰۰,۰۰۰,۰۰۰ تومان\",\"order\":2},{\"key\":\"pricePerMeter\",\"title\":\"قیمت هر متر\",\"value\":\"‏۵۰,۶۶۶,۰۰۰ تومان\",\"order\":5},{\"key\":\"area\",\"title\":\"متراژ\",\"value\":\"75\",\"order\":6},{\"key\":\"rooms\",\"title\":\"اتاق\",\"value\":\"دو\",\"order\":7},{\"key\":\"floor\",\"title\":\"طبقه\",\"value\":\"۱ از ۳\",\"order\":8},{\"key\":\"yearBuilt\",\"title\":\"سال ساخت\",\"value\":\"۱۳۹۵\",\"order\":9},{\"key\":\"totalFloors\",\"title\":\"تعداد کل طبقات\",\"value\":\"۳\",\"order\":10},{\"key\":\"unitsPerFloor\",\"title\":\"تعداد واحد در طبقه\",\"value\":\"۴\",\"order\":11},{\"key\":\"buildingDirection\",\"title\":\"جهت ساختمان\",\"value\":\"شمالی\",\"order\":12},{\"key\":\"deedType\",\"title\":\"سند\",\"value\":\"سایر\",\"order\":13},{\"key\":\"kitchenType\",\"title\":\"نوع آشپزخانه\",\"value\":\"اپن\",\"order\":14},{\"key\":\"buildingFacade\",\"title\":\"نمای ساختمان\",\"value\":\"سیمان\",\"order\":15},{\"key\":\"occupancyStatus\",\"title\":\"وضعیت سکونت\",\"value\":\"مالک سکونت دارد\",\"order\":16},{\"key\":\"address\",\"title\":\"آدرس\",\"value\":\"کرج, ساماندهی\",\"order\":18},{\"key\":\"elevator\",\"title\":\"آسانسور\",\"value\":\"دارد\",\"order\":19},{\"key\":\"parking\",\"title\":\"پارکینگ\",\"value\":\"ندارد\",\"order\":20},{\"key\":\"storage\",\"title\":\"انباری\",\"value\":\"ندارد\",\"order\":21},{\"key\":\"fullDescription\",\"title\":\"توضیحات\",\"value\":\"آپارتمان ۷۵ متری مجتمع سهند سازان\\nطبقه روی همکف ، ساختمان بتون آرمه حتی دیوارهاش\\nوام تسویه\\nسند ۵ برگی قابلیت درخواست سند تکبرگ\\nبدون کابینت و کمد دیواری\\nدیوار بلکا هست ، نقاشی نیست\\nآسانسور در حال راه اندازی\\nآب ، برق ، گاز اختصاصی\\n\\nلوکیشن آپارتمان در آگهی صحیح نمیباشد.\\n\\nلطفا در صورت تمایل  با توجه به مشخصات و قیمت ذکر شده  برای بازدید و دریافت آدرس هماهنگ کنید ، با تشکر ، مالک\\n\\nقیمت ۳ میلیارد و ۸۰۰ میلیون تومان مقطوع\",\"order\":23},{\"key\":\"url\",\"title\":\"لینک\",\"value\":\"https://divar.ir/v/gafis_qR\",\"order\":24}]', 'کرج', 'آپارتمان ۷۵ متری مجتمع سهند سازان\nطبقه روی همکف ، ساختمان بتون آرمه حتی دیوارهاش\nوام تسویه\nسند ۵ برگی قابلیت درخواست سند تکبرگ\nبدون کابینت و کمد دیواری\nدیوار بلکا هست ، نقاشی نیست\nآسانسور در حال راه اندازی\nآب ، برق ، گاز اختصاصی\n\nلوکیشن آپارتمان در آگهی صحیح نمیباشد.\n\nلطفا در صورت تمایل  با توجه به مشخصات و قیمت ذکر شده  برای بازدید و دریافت آدرس هماهنگ کنید ، با تشکر ، مالک\n\nقیمت ۳ میلیارد و ۸۰۰ میلیون تومان مقطوع', 'ساماندهی', '[\"https://postimage01.divarcdn.com/static/photo/neda/webp_post/z3UGWEbCerrJ4KIxqGz2kg/9258fbcd-935d-42c3-a46f-1186841c2ae9.webp\"]', b'0', b'1', 'فروش', 'apartment', '2026-09-15 04:39:50.000000', '2026-09-15 04:41:06.000000', 'آپارتمان فروشی انتهای کیانمهر شهرک ابریشم', 'gafis_qR', 'https://divar.ir/v/gafis_qR', 'فروش ابریشم پیام', b'0');
