INSERT INTO `property_listings` VALUES (113, '[{\"key\":\"title\",\"title\":\"عنوان\",\"value\":\"۱۱۰ متری بلوار جمهوری گوهردشت دوخوابه،تخلیه\",\"order\":1},{\"key\":\"deposit\",\"title\":\"ودیعه\",\"value\":\"1200000000\",\"order\":3},{\"key\":\"monthlyRent\",\"title\":\"اجاره ماهانه\",\"value\":\"16000000\",\"order\":4},{\"key\":\"area\",\"title\":\"متراژ\",\"value\":\"110\",\"order\":6},{\"key\":\"rooms\",\"title\":\"اتاق\",\"value\":\"دو\",\"order\":7},{\"key\":\"floor\",\"title\":\"طبقه\",\"value\":\"۲\",\"order\":8},{\"key\":\"yearBuilt\",\"title\":\"سال ساخت\",\"value\":\"۱۴۰۳\",\"order\":9},{\"key\":\"unitsPerFloor\",\"title\":\"تعداد واحد در طبقه\",\"value\":\"۱\",\"order\":11},{\"key\":\"buildingDirection\",\"title\":\"جهت ساختمان\",\"value\":\"جنوبی\",\"order\":12},{\"key\":\"address\",\"title\":\"آدرس\",\"value\":\"کرج, کوی بعثت\",\"order\":18},{\"key\":\"elevator\",\"title\":\"آسانسور\",\"value\":\"ندارد\",\"order\":19},{\"key\":\"parking\",\"title\":\"پارکینگ\",\"value\":\"ندارد\",\"order\":20},{\"key\":\"storage\",\"title\":\"انباری\",\"value\":\"دارد\",\"order\":21},{\"key\":\"fullDescription\",\"title\":\"توضیحات\",\"value\":\"خوش نقشه و بدون پرتی\\nساختمان ۳ طبقه | ۳ واحد | تک واحدی\\nجنوبی دو کله نور پذیرایی مربع                                                                                            بالکن قابل چیدمان                                                                                                                                                                                                                                                                      آیفون تصویری و اینترنت پر سرعت فیبر نوری\\nدو خواب کمد دیوار ی ریلی بزرگ\\nآشپزخانه MDF با گاز رو میزی و هود مخفی\\nدو عدد سرویس بهداشتی جداگانه ایرانی و فرنگی\\nپمپ آب با مخزن ذخیره \\nساختمان با محیطی آرام و مناسب خانواده\\nدسترسی عالی به مراکز خرید تفریحی و درمانی و غیره…..\\nاجاره این ملک دونفر / سه نفر\\nقابل تمدید برای سال های آینده\",\"order\":23},{\"key\":\"url\",\"ti