INSERT INTO `property_listings` VALUES (122, '[{\"key\":\"title\",\"title\":\"عنوان\",\"value\":\"آپارتمان مهرشهر کرج تهاتر با خودرو _ طلا _ دلار\",\"order\":1},{\"key\":\"price\",\"title\":\"قیمت کل\",\"value\":\"‏۵۰,۰۰۰,۰۰۰,۰۰۰ تومان\",\"order\":2},{\"key\":\"pricePerMeter\",\"title\":\"قیمت هر متر\",\"value\":\"‏۲۵۱,۲۵۶,۰۰۰ تومان\",\"order\":5},{\"key\":\"area\",\"title\":\"متراژ\",\"value\":\"199\",\"order\":6},{\"key\":\"rooms\",\"title\":\"اتاق\",\"value\":\"سه\",\"order\":7},{\"key\":\"floor\",\"title\":\"طبقه\",\"value\":\"۱\",\"order\":8},{\"key\":\"yearBuilt\",\"title\":\"سال ساخت\",\"value\":\"۱۴۰۴\",\"order\":9},{\"key\":\"deedType\",\"title\":\"سند\",\"value\":\"تک‌برگ\",\"order\":13},{\"key\":\"buildingFacade\",\"title\":\"نمای ساختمان\",\"value\":\"سنگ\",\"order\":15},{\"key\":\"address\",\"title\":\"آدرس\",\"value\":\"کرج, کوی مهر\",\"order\":18},{\"key\":\"elevator\",\"title\":\"آسانسور\",\"value\":\"دارد\",\"order\":19},{\"key\":\"parking\",\"title\":\"پارکینگ\",\"value\":\"دارد\",\"order\":20},{\"key\":\"storage\",\"title\":\"انباری\",\"value\":\"دارد\",\"order\":21},{\"key\":\"fullDescription\",\"title\":\"توضیحات\",\"value\":\"آپارتمان مهرشهر کرج\\n\\n ۱۹۹ متری: ۳ خواب ۱  خواب مستر ۲ پارکینگ سندی _ طبقه چهارم . \\n\\nتهاتر با خودروهای روز بازار / طلا / دلار تا بخشی از مبلغ و باقی نقد \\n\\nاز مجتمع مسکونی رویال پارک\\n(۸۰ واحدی شامل ۴ بلوک ۵ طبقه ۴ واحدی) \\n \\n✓ پارکینگ\\n✓ انباری\\n✓ بالکن\\n✓ ۲ آسانسور ۶ نفره\\n✓ داکت اسپلیت\\n✓ پکیچ \\n✓ کف سرامیک \\n✓ شیرآلات توکار\\n✓ وال هنگ\\n✓ آنتن مرکزی\\n✓ کمد دیواری ریلی\\n✓ دوربین مداربسته \\n✓ درب ضد سرقت\\n✓ سیستم اطفاء حریق مرکزی \\n✓ رو به نما\\n✓ نما ترکیبی\\n✓ زمین ۶۰۰۰ متری\\n✓ دو بر\\n✓ دارای سند رسمی معتبر \\n✓ با قدرالسهم از زمین \\n✓ سازه مقاوم در برابر زمین لرزه \\n+++++++++++++++++++++++++++++\\n✓ بیش از ۳۰۰۰ متر فضای سبز محوطه سازی با آلاچیق و آبنما\\n+++++++++++++++++++++++++++++\\n✓ اتاق بازی کودکان/سالن اجتماعات/سالن ورزش با ارتفاع ۳.۵ متر/سالن سینما/ لابی مجلل/ سرایداری\\nهر یک مج