INSERT INTO `property_listings` VALUES (147, '[{\"key\":\"title\",\"title\":\"عنوان\",\"value\":\"آپارتمان ۸۵ متری غرق نور طبقه پنجم در ششم شرقی\",\"order\":1},{\"key\":\"deposit\",\"title\":\"ودیعه\",\"value\":\"900000000\",\"order\":3},{\"key\":\"monthlyRent\",\"title\":\"اجاره ماهانه\",\"value\":\"24000000\",\"order\":4},{\"key\":\"area\",\"title\":\"متراژ\",\"value\":\"85\",\"order\":6},{\"key\":\"rooms\",\"title\":\"اتاق\",\"value\":\"دو\",\"order\":7},{\"key\":\"floor\",\"title\":\"طبقه\",\"value\":\"۵\",\"order\":8},{\"key\":\"yearBuilt\",\"title\":\"سال ساخت\",\"value\":\"۱۳۹۵\",\"order\":9},{\"key\":\"address\",\"title\":\"آدرس\",\"value\":\"کرج, آق تپه\",\"order\":18},{\"key\":\"elevator\",\"title\":\"آسانسور\",\"value\":\"دارد\",\"order\":19},{\"key\":\"parking\",\"title\":\"پارکینگ\",\"value\":\"دارد\",\"order\":20},{\"key\":\"storage\",\"title\":\"انباری\",\"value\":\"دارد\",\"order\":21},{\"key\":\"fullDescription\",\"title\":\"توضیحات\",\"value\":\"یه واحد ۸۵ متری در برج آموت ارم در کوچه ششم شرقی بلوار ارم مهرشهر داریم.\\n رهن کاملش ۱۲۰۰ میلیارده که تبدیل میشه.\\nبه مشتری خوب که سریع بیاد تخفیف هم میدیم.\\nشرایطش عالیه از همه نظر واحد تر و تمیز و تازه رنگ شده و تقریبا نوسازه ،آسانسور و انباری و پارکینگ و بالکن و ...داره.\\nویو عالیه\\nنورگیری فوق العاده\\nنقشه اش خیلی خوب و بدون پرتی فضاست.\\nنگهبانی شبانه روزی داره همراه با جمع آوری زباله.\\nداخل خود ساختمان آرایشگاه ،خیاطی،خانه بازی و ... هست که ورودیشون از یه سمت دیگه هستش و بسیار کاربردی میتونه باشه.\\nدسترسی سریع  به مکانهای رفاهی اعم از لبنیاتی ،سوپری،قصابی،نونوایی و مغازه های مختلف دیگر که دقیقا پایین مجتمع هستش\\nسر کوچه پارک داره\",\"order\":23},{\"key\":\"url\",\"title\":\"لینک\",\"value\":\"https://divar.ir/v/gavSYCH8\",\"order\":24}]', 'کرج', 'یه واحد ۸۵ متری در برج آموت ارم در کوچه ششم شرقی بلوار ارم مهرشهر داریم.\n رهن کاملش ۱۲۰۰ میلیارده که تبدیل میشه.\nبه مشتری خوب که سریع بیاد تخفیف هم میدیم.\nشرایطش عالیه از همه نظر واحد تر و تمیز و تازه رنگ شده و تقریبا نوسازه ،آسانسور و انباری و پارکینگ و بالکن و ...داره.\nویو عالیه\nنورگیری فوق العاده\nنقشه اش خیلی خوب و بدون پرتی فضاست.\nنگهبانی شبانه روزی داره همراه با جمع آوری زباله.\nداخل خود ساختمان آرایشگاه ،خیاطی،خانه بازی و ... هست که ورودیشون از یه سمت دیگه هستش و بسیار کاربردی میتونه باشه.\nدسترسی سریع  به مکانهای رفاهی اعم از لبنیاتی ،سوپری،قصابی،نونوایی و مغازه های مختلف دیگر که دقیقا پایین مجتمع هستش\nسر کوچه پارک داره', 'آق تپه', '[\"https://s100.divarcdn.com/static/photo/neda/webp_post/7wYZxfEB-_AMR32h8AlsiQ/ce6f8b2d-8f45-40c5-9133-77d76c161870.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/cEcgaHDvTB7qrw2RW5IHCA/869997f3-f063-409e-bf7a-39c883816f9e.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/qBqgulG-0GnNrG0fGmU8uw/d50baa32-c49d-4fec-beb2-90fa660cf154.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/yC3dovQx7yTAJYHHwdRY3A/3f5ccfeb-49e1-46c9-b16a-c483164a9345.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/lOvKrkvKOXcJ2mIzBVVWgg/294926d6-4a09-4d3f-b936-3a7602b1c895.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/elUFI6HMsLbyQYnBB3uCrA/034c6abd-16c7-4b89-ba32-f7b8626ba58f.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/iUTcg_r-2bPOLwsi7NX7_g/9430328b-6a5d-4c6c-a852-7d9faa89f4cc.webp\",\"https://s100.divarcdn.com/static/photo/neda/webp_post/QTrGkvHqctsVExzjDwXeqg/9c4e2d3d-7ed5-4764-bbb7-2d0905f76808.webp\"]', b'0', b'1', 'اجاره', 'apartment', '2026-09-20 11:30:37.000000', '2026-09-20 11:30:53.000000', 'آپارتمان ۸۵ متری غرق نور طبقه پنجم در ششم شرقی', 'gavSYCH8', 'https://divar.ir/v/gavSYCH8', 'اجاره آپارتمان مهرشهر', b'0');
